// Answers on one socket are written in arrival order: a frame the store made the waiter await must not let the next one overtake it.
function inOrder(
  answered: WeakMap<WebSocket, Promise<void>>,
  ws: WebSocket,
  answer: () => Promise<void>
): Promise<void> {
  const previous = answered.get(ws);
  const next = previous ? previous.then(answer, answer) : answer();
  answered.set(ws, next);
  return next;
}
```
