async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  sessionStore: SessionStore,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  await answerFrame(ws, sessionStore, validation);
}

async function answerFrame(ws: WebSocket, sessionStore: SessionStore, validation: ValidationResult): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await handleListSessions(ws, message, sessionStore);
}

// Answered here rather than behind a turn: a history request is not a turn, and it must not queue behind a streaming answer.
async function handleListSessions(
  ws: WebSocket,
  message: ListSessionsMessage,
  sessionStore: SessionStore
): Promise<void> {
  // The list is always the connection's own: the id was set at upgrade, and validation dropped any frame-supplied one.
  const userId = (ws as ExtWebSocket).userId;
  try {
    const summaries = await sessionStore.listFor?.(userId, {limit: message.limit, before: message.before});
    sendSessionList(ws, summaries ?? []);
  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listing conversations failed', {userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

